"""Write docs/asset-manifest.json (path, bytes, sha256, origin) and ASSET_CREDITS.md.

Origins:
  * Poly Haven assets: author list taken from the Poly Haven API at fetch time
    (.cache/fetch-manifest.json). Licence CC0 1.0.
  * Wikimedia Commons audio: author/licence from tools/assets/sources.json (checked on the file page).
  * Everything else is generated by this repository's tools (original, CC0).
"""
from __future__ import annotations
import hashlib, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SRC = json.loads((ROOT / "tools/assets/sources.json").read_text())
fetched = json.loads((ROOT / ".cache/fetch-manifest.json").read_text()) if (ROOT / ".cache/fetch-manifest.json").exists() else []
authors = {}
for r in fetched:
    if r.get("asset"):
        authors[r["asset"]] = r.get("authors", [])

def ph(asset_id):
    return {"origin": "Poly Haven", "page": f"https://polyhaven.com/a/{asset_id}", "authors": authors.get(asset_id, []), "licence": "CC0 1.0"}

def origin(rel: str):
    p = rel.split("/")
    if rel.startswith("assets/textures/"):
        tid = p[2]
        if tid == "vermilion_paint":
            return {"origin": "derived (this repo) from Poly Haven hinoki_planks + wood_peeling_paint_weathered", "licence": "CC0 1.0", "tool": "tools/assets/process_textures.py"}
        return {**ph(tid), "processing": "resized/re-encoded, ARM packed (tools/assets/process_textures.py)"}
    if rel.startswith("assets/sky/"):
        hid = SRC["polyhaven"]["hdri"][0]["id"]
        return {**ph(hid), "processing": "4k HDR -> LDR backdrop + original 1k HDR (tools/assets/process_textures.py)"}
    if rel.startswith("assets/models/props/"):
        mid = p[3].removesuffix(".glb")
        return {**ph(mid), "processing": "alpha merged, decimated, textures resized (tools/assets/process_models.mjs)"}
    if rel.startswith("assets/foliage/") and ("needle" in rel or "pine" in rel or "leaf-" in rel or rel.endswith("atlases.json")) and "bamboo" not in rel:
        return {"origin": "baked in this repo from Poly Haven CC0 models fir_sapling, pine_sapling_small, tree_small_02",
                "pages": [f"https://polyhaven.com/a/{i}" for i in ["fir_sapling", "pine_sapling_small", "tree_small_02"]],
                "authors": sorted(set(authors.get("fir_sapling", []) + authors.get("pine_sapling_small", []) + authors.get("tree_small_02", []))),
                "licence": "CC0 1.0", "tool": "tools/bake/bake-cards.mjs + tools/bake/compose_atlases.py"}
    if rel.startswith("assets/audio/higurashi-tanna"):
        a = SRC["commons"]["audio"][0]
        return {"origin": "Wikimedia Commons", "page": a["page"], "authors": [a["author"]], "licence": a["licence"], "licenceUrl": a["licenceUrl"],
                "processing": "high-pass 280 Hz, light denoise, loudness normalised, mono downmix (tools/assets/process_audio.sh)"}
    if rel.startswith("assets/licenses/"):
        return {"origin": "licence text"}
    tool = {
        "assets/models/trees/": "tools/trees/build-trees.mjs",
        "assets/models/architecture/": "tools/architecture/build.mjs",
        "assets/foliage/bamboo": "procedural (inline script in docs), original",
        "world/": "tools/world/generate_world.py",
    }
    for k, v in tool.items():
        if rel.startswith(k):
            return {"origin": "original (this repo)", "licence": "CC0 1.0", "tool": v}
    return {"origin": "original (this repo)", "licence": "CC0 1.0"}

entries = []
for base in [ROOT / "public/assets", ROOT / "public/world"]:
    for f in sorted(base.rglob("*")):
        if f.is_file():
            rel = str(f.relative_to(ROOT / "public"))
            entries.append({"path": rel, "bytes": f.stat().st_size, "sha256": hashlib.sha256(f.read_bytes()).hexdigest(), **origin(rel)})
(ROOT / "docs").mkdir(exist_ok=True)
(ROOT / "docs/asset-manifest.json").write_text(json.dumps(entries, ensure_ascii=False, indent=1))

# ---- credits ----------------------------------------------------------------
rows = []
for t in SRC["polyhaven"]["textures"]:
    rows.append(("テクスチャ", t["id"], ", ".join(authors.get(t["id"], [])), t["use"]))
for m in SRC["polyhaven"]["models"]:
    if (ROOT / f"public/assets/models/props/{m['id']}.glb").exists():
        rows.append(("3Dモデル", m["id"], ", ".join(authors.get(m["id"], [])), m["use"]))
for m in SRC["polyhaven"]["foliageSources"]:
    if m["id"] != "grass_medium_01":
        rows.append(("葉カードの原本", m["id"], ", ".join(authors.get(m["id"], [])), m["use"]))
h = SRC["polyhaven"]["hdri"][0]
rows.append(("HDRI", h["id"], ", ".join(authors.get(h["id"], [])), h["use"]))
a = SRC["commons"]["audio"][0]
total = sum(e["bytes"] for e in entries)
md = f"""# 使用素材と出典

このファイルは `python3 tools/assets/catalog.py` が生成します。全ファイルのパス・サイズ・SHA-256・出典は [`docs/asset-manifest.json`](docs/asset-manifest.json)（{len(entries)}ファイル、計{total/1e6:.1f}MB）にあります。

## 外部素材

### 録音（クレジット表記が必要）

| 素材 | 作者 | ライセンス | 配布ページ | 用途 |
|---|---|---|---|---|
| Tanna japonensis v01.ogg（ヒグラシ、2011年7月17日、川崎市麻生区） | {a['author']} | [{a['licence']}]({a['licenceUrl']}) | [Wikimedia Commons]({a['page']}) | ヒグラシの声（立体音源5基＋遠景） |

**表記例**：ヒグラシの録音 “Tanna japonensis v01.ogg” by Σ64, Wikimedia Commons, CC BY 4.0。加工：280Hz以下の除去、軽いノイズ低減、音量正規化、モノラル化。

`Higurashi 06c5856.ogg`（cory、CC BY 2.1 JP）も候補として確認しましたが、今回はWikimediaのレート制限（HTTP 429）で取得できず**未使用**です。Freesoundの`AkasakaHieJinjaCicadas_4mics.wav`（CC0）はダウンロードにログインが必要なため**未使用**です。

### Poly Haven（CC0 1.0。商用利用・改変・再配布可、表記義務なし）

ライセンスは https://polyhaven.com/license で確認しました（`public/assets/licenses/PolyHaven-asset-license.json`）。作者名は取得時にPoly HavenのAPIから記録したもので、任意のクレジットとして掲載します。

| 種別 | アセットID | 作者 | 用途 |
|---|---|---|---|
""" + "\n".join(f"| {k} | [{i}](https://polyhaven.com/a/{i}) | {au} | {u} |" for k, i, au, u in rows) + f"""

Poly Havenの植物モデル（`fir_sapling`、`pine_sapling_small`、`tree_small_02`）は、そのままではWebで扱えない重さ（数十〜数百MB）です。そのため、写真の葉のジオメトリを正射影で撮影して葉カード（`public/assets/foliage/*-albedo.png` / `*-normal.png`）に焼き、樹木は本リポジトリの生成器で作っています。生成した樹木は「Poly Havenの樹木スキャン」ではありません。

## 本プロジェクトで生成した素材（CC0 1.0として再利用可）

| 素材 | 生成元 |
|---|---|
| 地形の16-bit高さマップ、スプラットマスク、植生マスク、水田の水位、配置JSON | `tools/world/generate_world.py`（固定シード19940808） |
| 神社・鳥居・灯籠・狛犬・民家・蔵・納屋・電柱・橋・軽トラック・石段などのGLB | `tools/architecture/build.mjs`（実在の特定建築・作品の複製ではない独自設計） |
| 杉・檜・赤松・広葉樹・欅・竹のGLB（LOD0/LOD1） | `tools/trees/build-trees.mjs` |
| 竹の稈と葉のテクスチャ | 手続き的生成（本リポジトリ） |
| 朱塗りテクスチャ `vermilion_paint` | Poly Havenの2素材から派生（`process_textures.py`） |
| 川・風・葉擦れの音 | 実行時にWeb Audioでノイズから合成（`src/audio.ts`）。**実録ではありません** |

## ライブラリ

Three.js（MIT）、Rapier（Apache-2.0）、Vite（MIT）、TypeScript（Apache-2.0）、Playwright（Apache-2.0）、glTF-Transform（MIT）、meshoptimizer（MIT）、sharp（Apache-2.0）。

## 使っていない候補

- Sketchfabの日本建築モデル（CC BY）：ダウンロードにはSketchfabへのログインやAPIトークンが必要です。今回の環境では取得しておらず、使っていません。
- Kenney Nature Kit：ローポリ様式なので、写実性の要件に合わず採用していません。
- GrassSimulation（gzatravkin）：ライセンスの表示がないため、コードを参照・流用していません。
"""
(ROOT / "ASSET_CREDITS.md").write_text(md)
print("manifest", len(entries), "files", total, "bytes")
